/**
 * Calculate subtotal, discount and total for an invoice (in cents).
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }}
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    subtotal += total;
    const lineDiscount = total * (line.discountPercent ?? 0) / 100;
    discount += lineDiscount;
  }
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    total: Math.max(0, subtotal - discount),
  };
}

