  const expected = (5 * 8500) + (1 * 120000) + (100 * 50);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = addLine(r.value, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 1);
  assert.equal(r2.value.lines[0].qty, 2);
});

test('addLine increases qty for an existing SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 5);
});

test('addLine reports QTY_INVALID for bad quantities', () => {
