  assert.equal(r2.value.number, 'INV-2026-0004');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const nonDraft = { ...r.value, status: 'issued' };
  assert.deepEqual(issueInvoice(nonDraft, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  issueInvoice(r.value, []);
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.number, undefined);
});

